create extension if not exists pgcrypto;

create table if not exists public.angelcare_marketplace_family_accounts(id uuid primary key default gen_random_uuid(),public_reference text unique not null default ('FAM-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,10))),app_user_id uuid unique not null,display_name text not null,email text,phone text,city text,preferred_locale text not null default 'fr' check(preferred_locale in('fr','en','ar')),territory_id uuid,status text not null default 'incomplete' check(status in('active','incomplete','suspended','archived')),onboarding_status text not null default 'not_started' check(onboarding_status in('not_started','in_progress','completed')),consent_status text not null default 'pending' check(consent_status in('pending','granted','withdrawn')),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.angelcare_marketplace_family_children(id uuid primary key default gen_random_uuid(),public_reference text unique not null default ('CHD-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,10))),family_account_id uuid not null references public.angelcare_marketplace_family_accounts(id) on delete cascade,first_name text not null,birth_date date not null,age_group text not null,gender text,school_level text,languages text[] not null default '{}',interests text[] not null default '{}',allergies text,medical_boundaries text,support_notes text,status text not null default 'active' check(status in('active','inactive','archived')),created_by uuid,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.angelcare_marketplace_family_consents(id uuid primary key default gen_random_uuid(),family_account_id uuid not null references public.angelcare_marketplace_family_accounts(id) on delete cascade,child_id uuid references public.angelcare_marketplace_family_children(id) on delete cascade,consent_type text not null,status text not null check(status in('granted','withdrawn')),version text not null,evidence jsonb not null default '{}',granted_by uuid,granted_at timestamptz,withdrawn_at timestamptz,created_at timestamptz not null default now());
create table if not exists public.angelcare_marketplace_family_diagnostics(id uuid primary key default gen_random_uuid(),public_reference text unique not null default ('DIA-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,10))),family_account_id uuid not null references public.angelcare_marketplace_family_accounts(id) on delete cascade,child_id uuid not null references public.angelcare_marketplace_family_children(id),status text not null default 'draft' check(status in('draft','submitted','reviewed','superseded')),schedule_needs jsonb not null default '{}',development_goals text[] not null default '{}',routine_needs text[] not null default '{}',safety_constraints text[] not null default '{}',family_priorities text[] not null default '{}',free_context text,recommendation_summary text,submitted_at timestamptz,reviewed_at timestamptz,created_by uuid,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.angelcare_marketplace_family_quote_requests(id uuid primary key default gen_random_uuid(),public_reference text unique not null default ('REQ-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,10))),family_account_id uuid not null references public.angelcare_marketplace_family_accounts(id),child_id uuid references public.angelcare_marketplace_family_children(id),diagnostic_id uuid references public.angelcare_marketplace_family_diagnostics(id),service_family text not null,city text not null,requested_start_date date,schedule jsonb not null default '{}',duration_expectation text,location_notes text,priorities text[] not null default '{}',status text not null default 'submitted' check(status in('draft','submitted','qualified','proposal_ready','accepted','declined','cancelled')),owner_id uuid,qualification_notes text,next_action text,submitted_at timestamptz,qualified_at timestamptz,created_by uuid,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.angelcare_marketplace_family_missions(id uuid primary key default gen_random_uuid(),public_reference text unique not null default ('MSN-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,10))),family_account_id uuid not null references public.angelcare_marketplace_family_accounts(id),quote_request_id uuid references public.angelcare_marketplace_family_quote_requests(id),child_id uuid references public.angelcare_marketplace_family_children(id),status text not null default 'requested' check(status in('requested','scheduled','assigned','in_progress','completed','cancelled')),service_type text not null,starts_at timestamptz,ends_at timestamptz,city text,provider_display_name text,next_action text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.angelcare_marketplace_family_mission_timeline(id uuid primary key default gen_random_uuid(),mission_id uuid not null references public.angelcare_marketplace_family_missions(id) on delete cascade,event_type text not null,title text not null,description text,visible_to_family boolean not null default true,occurred_at timestamptz not null default now(),created_by uuid,created_at timestamptz not null default now());
create table if not exists public.angelcare_marketplace_family_mission_reports(id uuid primary key default gen_random_uuid(),mission_id uuid not null references public.angelcare_marketplace_family_missions(id) on delete cascade,status text not null default 'draft' check(status in('draft','submitted','validated','correction_required','published')),summary text not null,activities jsonb not null default '[]',observations jsonb not null default '[]',recommendations jsonb not null default '[]',published_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.angelcare_marketplace_family_support_tickets(id uuid primary key default gen_random_uuid(),public_reference text unique not null default ('SUP-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,10))),family_account_id uuid not null references public.angelcare_marketplace_family_accounts(id),subject text not null,category text not null,priority text not null default 'normal' check(priority in('normal','high','urgent')),status text not null default 'open' check(status in('open','triaged','in_progress','waiting_family','resolved','closed')),owner_id uuid,next_action text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),resolved_at timestamptz);
create table if not exists public.angelcare_marketplace_family_support_messages(id uuid primary key default gen_random_uuid(),ticket_id uuid not null references public.angelcare_marketplace_family_support_tickets(id) on delete cascade,author_type text not null check(author_type in('family','staff','system')),author_id uuid,body text not null,visible_to_family boolean not null default true,created_at timestamptz not null default now());
create table if not exists public.angelcare_marketplace_family_documents(id uuid primary key default gen_random_uuid(),family_account_id uuid not null references public.angelcare_marketplace_family_accounts(id),document_type text not null,title text not null,storage_path text not null,status text not null default 'active',visible_to_family boolean not null default true,created_at timestamptz not null default now());
create table if not exists public.angelcare_marketplace_family_feedback(id uuid primary key default gen_random_uuid(),family_account_id uuid not null references public.angelcare_marketplace_family_accounts(id),mission_id uuid references public.angelcare_marketplace_family_missions(id),rating int check(rating between 1 and 5),comments text,status text not null default 'submitted',created_at timestamptz not null default now());

create or replace function public.angelcare_marketplace_create_family_support_ticket(p_family_account_id uuid,p_subject text,p_category text,p_priority text,p_message text,p_actor_id uuid) returns public.angelcare_marketplace_family_support_tickets language plpgsql security definer set search_path=public as $$declare r public.angelcare_marketplace_family_support_tickets;begin insert into public.angelcare_marketplace_family_support_tickets(family_account_id,subject,category,priority,status,next_action)values(p_family_account_id,p_subject,p_category,p_priority,'open','Prise en charge par le support ANGELCARE.') returning * into r;insert into public.angelcare_marketplace_family_support_messages(ticket_id,author_type,author_id,body,visible_to_family)values(r.id,'family',p_actor_id,p_message,true);return r;end$$;

create or replace view public.angelcare_marketplace_admin_search_v as
select 'module'::text object_type,m.id::text object_id,m.module_key public_reference,m.name title,coalesce(m.description,'') subtitle,m.status,m.owner_role::text owner_id,null::uuid territory_id,null::uuid tenant_id,m.route_prefix route,setweight(to_tsvector('simple',coalesce(m.name,'')),'A')||setweight(to_tsvector('simple',coalesce(m.description,'')),'B') search_document,1::real search_rank,m.updated_at from public.angelcare_marketplace_modules m
union all select 'territory',t.id::text,t.territory_code,t.name,t.country_code,t.status,t.owner_id::text,t.id,null::uuid,'/angelcare-marketplace/admin/territories/'||t.territory_code,to_tsvector('simple',coalesce(t.name,'')||' '||coalesce(t.territory_code,'')),1::real,t.updated_at from public.angelcare_marketplace_territories t
union all select 'family_account',a.id::text,a.public_reference,a.display_name,coalesce(a.city,'')||' · '||coalesce(a.email,''),a.status,null::text,a.territory_id,null::uuid,'/angelcare-marketplace/admin/families',to_tsvector('simple',coalesce(a.public_reference,'')||' '||coalesce(a.display_name,'')||' '||coalesce(a.email,'')||' '||coalesce(a.city,'')),1::real,a.updated_at from public.angelcare_marketplace_family_accounts a
union all select 'family_quote_request',r.id::text,r.public_reference,r.service_family,coalesce(r.city,'')||' · '||coalesce(r.next_action,''),r.status,r.owner_id::text,a.territory_id,null::uuid,'/angelcare-marketplace/admin/family-requests/'||r.id,to_tsvector('simple',coalesce(r.public_reference,'')||' '||coalesce(r.service_family,'')||' '||coalesce(r.city,'')),1::real,r.updated_at from public.angelcare_marketplace_family_quote_requests r join public.angelcare_marketplace_family_accounts a on a.id=r.family_account_id;

insert into public.angelcare_marketplace_permissions(permission_key,name,category,sensitive) values
('marketplace.family.access','Accéder à l’espace famille','Family',false),('marketplace.family.dashboard','Voir le dashboard famille','Family',false),('marketplace.family.profile.view','Voir le profil famille','Family',false),('marketplace.family.profile.manage','Gérer le profil famille','Family',true),('marketplace.family.children.view','Voir les enfants','Family',false),('marketplace.family.children.manage','Gérer les enfants','Family',true),('marketplace.family.diagnostics.view','Voir les diagnostics','Family',false),('marketplace.family.diagnostics.create','Créer un diagnostic','Family',true),('marketplace.family.requests.view','Voir les demandes','Family',false),('marketplace.family.requests.create','Créer une demande','Family',true),('marketplace.family.requests.manage','Gérer les demandes','Family Admin',true),('marketplace.family.missions.view','Voir les missions','Family',false),('marketplace.family.reports.view','Voir les rapports','Family',false),('marketplace.family.support.view','Voir le support','Family',false),('marketplace.family.support.create','Ouvrir un ticket','Family',true),('marketplace.family.documents.view','Voir les documents','Family',false),('marketplace.family.documents.manage','Gérer les documents','Family',true),('marketplace.family.feedback.create','Créer un feedback','Family',true),('marketplace.family.feedback.view','Voir les feedbacks','Family',false),('marketplace.family.admin.view','Voir Family Command','Family Admin',false),('marketplace.family.admin.manage','Gérer les familles','Family Admin',true),('marketplace.family.requests.qualify','Qualifier les demandes','Family Admin',true),('marketplace.family.missions.manage','Gérer les missions familles','Family Admin',true),('marketplace.family.reports.publish','Publier un rapport famille','Family Admin',true),('marketplace.family.support.manage','Gérer le support famille','Family Admin',true),('marketplace.family.export','Exporter les preuves familles','Family Admin',true) on conflict(permission_key) do update set name=excluded.name,category=excluded.category,sensitive=excluded.sensitive;
insert into public.angelcare_marketplace_roles(role_key,name,description,system_role,active) values('marketplace_family_user','Famille ANGELCARE','Accès limité au propre dossier famille.',true,true),('marketplace_family_coordinator','Coordinatrice familles','Qualification, suivi et support des familles.',true,true) on conflict(role_key) do update set name=excluded.name,description=excluded.description,active=true;
insert into public.angelcare_marketplace_role_permissions(role_key,permission_key) select 'marketplace_family_user',permission_key from public.angelcare_marketplace_permissions where permission_key in('marketplace.family.access','marketplace.family.dashboard','marketplace.family.profile.view','marketplace.family.profile.manage','marketplace.family.children.view','marketplace.family.children.manage','marketplace.family.diagnostics.view','marketplace.family.diagnostics.create','marketplace.family.requests.view','marketplace.family.requests.create','marketplace.family.missions.view','marketplace.family.reports.view','marketplace.family.support.view','marketplace.family.support.create','marketplace.family.documents.view','marketplace.family.feedback.create','marketplace.family.feedback.view') on conflict do nothing;
insert into public.angelcare_marketplace_role_permissions(role_key,permission_key) select r.role_key,p.permission_key from public.angelcare_marketplace_roles r cross join public.angelcare_marketplace_permissions p where r.role_key in('marketplace_super_admin','marketplace_executive','marketplace_family_coordinator') and p.permission_key like 'marketplace.family.%' on conflict do nothing;
update public.angelcare_marketplace_modules set status='enabled',enabled=true,health_status='healthy',route_prefix='/angelcare-marketplace/family/dashboard',required_permissions=array['marketplace.family.access']::text[],version=version+1,updated_at=now() where introduced_by_mega_zip=7;
insert into public.angelcare_marketplace_feature_flags(flag_key,name,description,enabled,status,reason) values('marketplace.family-experience.enabled','Expérience famille','Profils enfants, diagnostic, demande, missions, rapports et support.',true,'active','Ultra Delivery 1/5') on conflict(flag_key) do update set enabled=true,status='active',updated_at=now();

alter table public.angelcare_marketplace_family_accounts enable row level security;alter table public.angelcare_marketplace_family_children enable row level security;alter table public.angelcare_marketplace_family_consents enable row level security;alter table public.angelcare_marketplace_family_diagnostics enable row level security;alter table public.angelcare_marketplace_family_quote_requests enable row level security;alter table public.angelcare_marketplace_family_missions enable row level security;alter table public.angelcare_marketplace_family_mission_timeline enable row level security;alter table public.angelcare_marketplace_family_mission_reports enable row level security;alter table public.angelcare_marketplace_family_support_tickets enable row level security;alter table public.angelcare_marketplace_family_support_messages enable row level security;alter table public.angelcare_marketplace_family_documents enable row level security;alter table public.angelcare_marketplace_family_feedback enable row level security;
revoke all on table public.angelcare_marketplace_family_accounts,public.angelcare_marketplace_family_children,public.angelcare_marketplace_family_consents,public.angelcare_marketplace_family_diagnostics,public.angelcare_marketplace_family_quote_requests,public.angelcare_marketplace_family_missions,public.angelcare_marketplace_family_mission_timeline,public.angelcare_marketplace_family_mission_reports,public.angelcare_marketplace_family_support_tickets,public.angelcare_marketplace_family_support_messages,public.angelcare_marketplace_family_documents,public.angelcare_marketplace_family_feedback from anon,authenticated;
grant all on table public.angelcare_marketplace_family_accounts,public.angelcare_marketplace_family_children,public.angelcare_marketplace_family_consents,public.angelcare_marketplace_family_diagnostics,public.angelcare_marketplace_family_quote_requests,public.angelcare_marketplace_family_missions,public.angelcare_marketplace_family_mission_timeline,public.angelcare_marketplace_family_mission_reports,public.angelcare_marketplace_family_support_tickets,public.angelcare_marketplace_family_support_messages,public.angelcare_marketplace_family_documents,public.angelcare_marketplace_family_feedback to service_role;
grant execute on function public.angelcare_marketplace_create_family_support_ticket(uuid,text,text,text,text,uuid) to service_role;
